fragment.set-body:
@{
    var request = JObject.Parse((string)context.Variables["model-request-body"]);
    var input = request["input"] == null
      ? ""
      : request["input"].ToString(Newtonsoft.Json.Formatting.None);
    var safetyInput = input.Substring(0, Math.Min(input.Length, 10000));
    return new JObject(new JProperty("input", safetyInput)).ToString(Newtonsoft.Json.Formatting.None);
  }
